use base64::{Engine,engine::general_purpose::STANDARD};
use serde_json::{json,Value};
use std::{collections::BTreeMap,path::PathBuf};
use bisect_report::{label_chain::{check_config_sha,check_cross_sha,format_link}};

pub(crate) fn verify(registry_json:Option<String>,files:BTreeMap<String,String>,label:String,year_filter:Option<String>)->Result<Value,String>{
 let token=|s:&str|!s.is_empty()&&s.len()<=100&&s.bytes().all(|b|b.is_ascii_alphanumeric()||b"_-".contains(&b))&&!["__proto__","constructor","prototype"].contains(&s);
 let safe=|p:&str|!p.is_empty()&&p.len()<=200&&p.bytes().all(|b|b.is_ascii_alphanumeric()||b"_./ -".contains(&b))&&!p.split('/').any(|x|x.is_empty()||[".","..","__proto__","constructor","prototype"].contains(&x));
 if !token(&label)||year_filter.as_ref().is_some_and(|y|!token(y)){return Err("Supply a safe label and optional year filter, each at most 100 ASCII characters.".into());}
 if registry_json.as_ref().is_some_and(|t|t.len()>1024*1024)||files.len()>512||files.values().map(String::len).sum::<usize>()>24*1024*1024{return Err("Select a registry up to 1 MiB and up to 512 files totaling 16 MiB.".into());}
 let registry=bisect_report::label_registry::parse(registry_json.as_deref().unwrap_or(""))?;
 if registry.len()>500||registry.values().any(|e|e.built.len()>100||e.analyzed.len()>100||e.reported.len()>100){return Err("Registry supports up to 500 labels and 100 stage years per label in the browser.".into());}
 let entry=registry.get(&label).ok_or_else(||format!("[CONFIG] verify: label '{label}' does not exist in registry.\nRun: bisect ls    to see available labels."))?;
 let years=year_filter.map(|y|vec![y]).unwrap_or_else(||entry.built.clone());if years.iter().any(|y|!token(y)){return Err("Selected registry years must be safe relative path components.".into());}
 let mut decoded=BTreeMap::new();let mut total=0;let mut folded=std::collections::BTreeSet::new();for(p,b)in files{if !safe(&p)||!folded.insert(p.to_ascii_lowercase()){return Err("Unsafe or case-colliding label evidence path.".into());}let bytes=STANDARD.decode(b).map_err(|_|"Invalid label evidence base64.")?;total+=bytes.len();if total>16*1024*1024{return Err("Label evidence exceeds 16 MiB.".into());}decoded.insert(p,bytes);}
 let key=|p:&std::path::Path|->Option<String>{let normalized=p.to_string_lossy().replace('\\',"/");if safe(&normalized){Some(normalized)}else{None}};
 let exists=|p:&std::path::Path|key(p).is_some_and(|k|decoded.contains_key(&k));let read=|p:&std::path::Path|key(p).and_then(|k|decoded.get(&k).cloned());
 let mut console=String::new();let mut rows=Vec::new();let mut overall=true;let mut report_bytes=0usize;
 for year in &years{console.push_str(&format!("--- {label} / {year} ---\n"));let run=PathBuf::from("runs").join(&label).join(year).join("index.json");let analysis=PathBuf::from("analysis").join(&label).join(year).join("index.json");let report=PathBuf::from("reports").join(&label).join(year).join("index.json");let links=[check_config_sha(&label,&run,&exists,&read),check_cross_sha("Build index",&run,&analysis,"run_index_sha256",&exists,&read),check_cross_sha("Analysis index",&analysis,&report,"analysis_index_sha256",&exists,&read)];let mut cells=Vec::new();for link in links{console.push_str(&format_link(&link));let ok=link.is_ok();overall&=ok;let mut value=serde_json::to_value(&link).map_err(|e|e.to_string())?;value["match"]=json!(ok);report_bytes+=serde_json::to_vec(&value).map_err(|e|e.to_string())?.len();if report_bytes+console.len()>8*1024*1024{return Err("Label verification report exceeds the 8 MiB browser limit.".into());}cells.push(value);}console.push('\n');rows.push(json!({"year":year,"links":cells}));}
 let status=if years.is_empty(){console=format!("verify: label '{label}' has no built years — nothing to verify.\n");"nothing-to-verify"}else if overall{console.push_str("Verdict: VERIFIED\n");"verified"}else{console.push_str("Verdict: FAILED\n");"failed"};
 Ok(json!({"schema_version":"bisect-label-chain-v1","status":status,"native_exit_code":if overall{0}else{1},"label":label,"years":rows,"native_console_text":console,"scope":"Shared native label verifier: configuration bytes against build index, build index bytes against analysis index, and analysis index bytes against report index. All three links are required for each selected year; missing/unreadable sources or recorded hashes fail the native verdict. With no built years the native command succeeds without verifying anything. Registry stage records and referenced paths are untrusted declarations. Only explicitly supplied relative files are accessible; unsafe or absolute config paths remain unavailable and are never opened or fetched. This does not check district assignments, populations, contiguity, per-state analysis files, authorship, signatures or legal compliance. Imported results remain unverified until an explicit Run."}))
}
